namespace Shader {

enum class Qualifier : u8 {
    None,
    Smooth,
    NoPerspective,
    PerVertex,
    Flat,
    Centroid,
    Sample,
};

// PS4Recomp: T# tables a shader indexes at run time (LowerDynamicImageTable). The T# of a site
// is read at dword offset first + stride * index of a buffer; the entries a draw can reach are
// copied into the flattened user data by the SRT program and bound as ordinary images.
enum class ImageTableKind : u8 {
    None,    // no bound fits (more than MaxImageTableEntries entries): the sites read the null image
    Records, // the table buffer's V# bounds it: entries k = 0.. with dword first + stride * k in it
    Indexed, // the index is read from a record of a bounded buffer: one entry per distinct index
             // its records hold, and index 0 (what an index read past that buffer returns)
    Loop,    // the index is a loop counter 0, 1, ... N - 1, N read from the flattened user data
};

// Entries bound per table at most (the discrete form: one sample per entry, then a select)
constexpr u32 MaxImageTableEntries = SrtMaxTableIndices;
// Records of an index buffer the SRT program scans for an Indexed table at most
constexpr u32 MaxImageTableIndexRecords = 4096;

// How many entries of a table a draw reaches, from the draw's flattened user data.
struct ImageTableBound {
    ImageTableKind kind{};
    // Records: the elements (first + stride * k) of the table buffer whose first dword lies
    // below its size (an s_buffer_load past that reads 0): the buffer's V# at flat[vs]
    SharpLocation vs{};
    u32 size_imm{};
    u32 first_dw{};
    u32 stride_dw{};
    // Loop: N = flat[count_dw], compared with the counter as `compare`. Indexed: flat[count_dw]
    // is the number of distinct indices (SrtOp::CollectIndices, ~0u: too many records)
    SharpLocation count_dw{};
    LoopCompare compare{};

    u64 Entries(const u32* flat) const {
        if (kind == ImageTableKind::Loop) {
            return DynamicLoopEntries(flat[count_dw], compare);
        }
        if (kind == ImageTableKind::Indexed) {
            return flat[count_dw];
        }
        const u64 size = SrtBufferBytes(flat + vs, size_imm);
        const u64 first_end = (u64(first_dw) + 1) * 4;
        return size < first_end ? 0 : (size - first_end) / (u64(stride_dw) * 4) + 1;
    }
};

// Bucket of a table's entry count in the specialization: 1, 2, 4, 8 entries, or more
inline u8 ImageTableBucket(u64 entries) {
    return entries <= 1 ? 0 : entries <= 2 ? 1 : entries <= 4 ? 2 : entries <= 8 ? 3 : 4;
}
inline u32 ImageTableBucketEntries(u8 bucket) {
    return 1u << bucket;
}

struct ImageTableResource {
    ImageTableKind kind{}; // the bound the entries were made for (None: none fits, no entries)
    u32 table_buffer{};    // Info::buffers index of the buffer the T#s are read from
    u32 first_dw{};        // T# dword i at first + i + stride * index
    u32 stride_dw{};
    u32 num_dwords{};      // 8, or 4 for r128
    u32 index_buffer = ~0u; // Indexed: Info::buffers index of the buffer holding the indices
    u32 num_entries{};     // images bound (ImageResource::table == this table)
    u32 reached{};         // entries the compiling draw reaches (`kind`'s bound)
    u32 num_sites{};       // image instructions reading the table
    u32 num_bounds{};
    std::array<ImageTableBound, 3> bounds{}; // every bound the table's form allows
};
using ImageTableList = boost::container::static_vector<ImageTableResource, 8>;

/**
 * Contains general information generated by the shader recompiler for an input program.
 */
struct InfoPersistent {
    BufferResourceList buffers;
    ImageResourceList images;
    SamplerResourceList samplers;
    FMaskResourceList fmasks;

    u32 fetch_shader_sgpr_base{};
    u32 shared_memory_scratch_size{};

    u64 pgm_hash{};

    s32 tess_consts_dword_offset = -1;
    IR::ScalarReg tess_consts_ptr_base = IR::ScalarReg::Max;
    HwStage hw_stage;
    SwStage sw_stage;

    u8 mrt_mask{};
    bool has_fetch_shader{};
    // PS4Recomp: the VS calls a fetch shader whose instructions are translated into it (its
    // buffer loads read the vertex buffers; has_fetch_shader is false: no vertex attributes).
    // Translator::EmitFetch does it when an attribute's V# is not Gcn::IsVertexFetchable.
    bool fetch_shader_inlined{};
    // PS4Recomp: why (Gcn::VertexFetchProblem bits of the first attribute Metal cannot fetch) and
    // which attribute that is, when fetch_shader_inlined
    u8 fetch_inline_reason{};
    u8 fetch_inline_attrib{};
    bool has_bitwise_xor{};
    bool uses_dma{};
    // PS4Recomp: buffer accesses through V#s loaded at run time read and write guest memory
    // through the guest page table (GCN_BUFFER_BDA_PAGETABLE) and report to the fault buffer
    bool uses_guest_memory{};
    // PS4Recomp: image reads through a T# loaded at run time that read the null image
    u32 null_image_reads{};
    // PS4Recomp: T# tables the shader indexes at run time (their entries are images)
    ImageTableList image_tables;
    // PS4Recomp: always 0 (v_writelane was emitted as 0; now a per-lane select), kept for the API
    u32 zeroed_write_lanes{};
    // PS4Recomp: wave64 EXEC-divergent ifs and loops that needed the whole wave but were left per
    // subgroup (predicate_wave64_pass.cpp fell back), and cross-lane reads (v_readlane,
    // v_readfirstlane, v_mbcnt) left per subgroup in non-uniform control flow (known gaps)
    u32 unpredicated_wave_regions{};
    u32 per_subgroup_lane_ops{};
    // PS4Recomp: s_endpgm (or an unreachable end) in EXEC-divergent code kept as an end of the
    // lanes that reach it, because nothing after it needs the whole wave (predicate_wave64_pass.cpp,
    // EndsNeedTheWave). GCN ends the whole wave there; the wave's other lanes run on (known gap).
    u32 per_lane_ends{};

    InfoPersistent() = default;
    InfoPersistent(HwStage hw_stage_, SwStage sw_stage_, u64 pgm_hash_)
        : hw_stage{hw_stage_}, sw_stage{sw_stage_}, pgm_hash{pgm_hash_} {}
};

struct Info : InfoPersistent {
    struct AttributeFlags {
        bool Get(IR::Attribute attrib, u32 comp = 0) const {
            return flags[Index(attrib)] & (1 << comp);
        }

        bool GetAny(IR::Attribute attrib) const {
            return flags[Index(attrib)];
        }

        void Set(IR::Attribute attrib, u32 comp = 0) {
            flags[Index(attrib)] |= (1 << comp);
        }

        u32 NumComponents(IR::Attribute attrib) const {
            return 4;
        }

        static size_t Index(IR::Attribute attrib) {
            return static_cast<size_t>(attrib);
        }

        std::array<u8, IR::NumAttributes> flags;
    };

    enum class ReadConstType {
        None = 0,
        Immediate = 1 << 0,
        Dynamic = 1 << 1,
    };

    struct Interpolation {
        Qualifier primary;
        Qualifier auxiliary;
    };

    std::span<const u32> user_data;
    std::vector<u32> flattened_ud_buf;
    PersistentSrtInfo srt_info;

    AttributeFlags loads{};
    AttributeFlags stores{};

    ReadConstType readconst_types{};
    CopyShaderData gs_copy_data;
    u32 uses_patches{};

    VAddr pgm_base;
    bool has_storage_images{};
    bool has_discard{};
    bool has_image_gather{};
    bool has_image_query{};
    bool has_flatbuf{};
    bool uses_buffer_atomic_float_min_max{};
    bool uses_image_atomic_float_min_max{};
    bool uses_lane_id{};
    bool uses_shader_clock{};
    bool uses_group_quad{};
    bool uses_group_shuffle{};
    bool uses_group_ballot{};
    IR::Type shared_types{};
    bool uses_fp16{};
    bool uses_fp64{};
    bool uses_pack_10_11_11{};
    bool uses_unpack_10_11_11{};
    bool uses_buffer_int64_atomics{};
    bool uses_shared_int64_atomics{};
    bool stores_tess_level_outer{};
    bool stores_tess_level_inner{};
    bool translation_failed{};

    std::array<Interpolation, IR::NumParams> fs_interpolation{};

    Info() = default;
    Info(HwStage stage_, SwStage l_stage_, ShaderParams params)
        : InfoPersistent(stage_, l_stage_, params.hash), pgm_base{params.Base()},
          user_data{params.user_data} {}

    template <typename T>
    inline T ReadUdSharp(u32 sharp_idx) const {
        return *reinterpret_cast<const T*>(&flattened_ud_buf[sharp_idx]);
    }

    template <typename T>
    T ReadUdReg(u32 ptr_index, u32 dword_offset) const {
        T data;
        if (ptr_index != IR::NumScalarRegs) {
            u64 base;
            std::memcpy(&base, &user_data[ptr_index], sizeof(base));
            base &= 0xFFFFFFFFFFFFULL;
            GcnShim::ReadGuest(base + u64(dword_offset) * 4, &data, sizeof(T));
            return data;
        }
        std::memcpy(&data, user_data.data() + dword_offset, sizeof(T));
        return data;
    }

    void AddBindings(Backend::Bindings& bnd) const {
        bnd.buffer += buffers.size();
        bnd.unified += buffers.size() + images.size() + samplers.size();
    }

    void RefreshFlatBuf() {
        flattened_ud_buf.resize(srt_info.flattened_bufsize_dw);
        ASSERT(user_data.size() <= NUM_USER_DATA_REGS);
        std::memcpy(flattened_ud_buf.data(), user_data.data(), user_data.size_bytes());
        if (!srt_info.program.empty()) {
            const auto& gm = GcnShim::CurrentGuestMemory();
            RunSrtProgram(srt_info.program, user_data.data(), flattened_ud_buf.data(), gm.read,
                          gm.ctx);
        }
    }

    void ReadTessConstantBuffer(TessellationDataConstantBuffer& tess_constants) const {
        ASSERT(tess_consts_dword_offset >= 0); // We've already tracked the V# UD
        auto buf = ReadUdReg<AmdGpu::Buffer>(static_cast<u32>(tess_consts_ptr_base),
                                             static_cast<u32>(tess_consts_dword_offset));
        VAddr tess_constants_addr = buf.base_address;
        GcnShim::ReadGuest(tess_constants_addr, &tess_constants, sizeof(tess_constants));
    }

    void Serialize(Serialization::Archive& ar) const;
    bool Deserialize(Serialization::Archive& ar);
};
DECLARE_ENUM_FLAG_OPERATORS(Info::ReadConstType);

} // namespace Shader
